import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_cos_sim_loss_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Block-wide reduce function for sums
__inline__ __device__ void blockReduce(volatile float* sdata, int tid) {
    sdata[tid] += sdata[tid + 128];
    sdata[tid] += sdata[tid + 64];
    sdata[tid] += sdata[tid + 32];
    sdata[tid] += sdata[tid + 16];
    sdata[tid] += sdata[tid + 8];
    sdata[tid] += sdata[tid + 4];
    sdata[tid] += sdata[tid + 2];
    sdata[tid] += sdata[tid + 1];
}

// Each block handles one row of predictions/targets
// out[0] accumulates the sum of (1 - cos_sim) across all rows
__global__ void fused_cosine_similarity_loss_kernel(
    const float* __restrict__ pred,
    const float* __restrict__ targ,
    float* __restrict__ out,
    const int batch_size,
    const int feature_size
){
    int row = blockIdx.x;
    if (row >= batch_size) return;

    extern __shared__ float smem[];
    float* sdot  = smem;                  // partial sums for dot
    float* ssumA = smem + blockDim.x;     // partial sums for normA
    float* ssumB = smem + 2 * blockDim.x; // partial sums for normB

    // Initialize shared memory
    int tid = threadIdx.x;
    sdot[tid]  = 0.0f;
    ssumA[tid] = 0.0f;
    ssumB[tid] = 0.0f;

    // Compute partial sums for this row
    for (int j = tid; j < feature_size; j += blockDim.x){
        float pval = pred[row * feature_size + j];
        float tval = targ[row * feature_size + j];
        sdot[tid]  += pval * tval;
        ssumA[tid] += pval * pval;
        ssumB[tid] += tval * tval;
    }
    __syncthreads();

    // Block reduce
    for (int offset = blockDim.x / 2; offset > 32; offset >>= 1){
        if (tid < offset){
            sdot[tid]  += sdot[tid + offset];
            ssumA[tid] += ssumA[tid + offset];
            ssumB[tid] += ssumB[tid + offset];
        }
        __syncthreads();
    }
    if (tid < 32) {
        blockReduce(sdot, tid);
        blockReduce(ssumA, tid);
        blockReduce(ssumB, tid);
    }
    __syncthreads();

    // Compute final cost_i in thread 0
    if (tid == 0) {
        float dot  = sdot[0];
        float normA = sqrtf(ssumA[0]);
        float normB = sqrtf(ssumB[0]);
        float cos = dot / (normA * normB + 1e-12f);
        float cost_i = 1.0f - cos;
        atomicAdd(out, cost_i);
    }
}

torch::Tensor fused_cosine_similarity_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure inputs are on CUDA float
    TORCH_CHECK(predictions.is_cuda(), "predictions must be CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be CUDA tensor");
    TORCH_CHECK(predictions.dtype() == torch::kFloat, "predictions must be float tensor");
    TORCH_CHECK(targets.dtype() == torch::kFloat, "targets must be float tensor");
    TORCH_CHECK(predictions.dim() == 2, "predictions must have 2 dimensions");
    TORCH_CHECK(targets.dim() == 2, "targets must have 2 dimensions");
    TORCH_CHECK(predictions.size(0) == targets.size(0), "batch sizes must match");
    TORCH_CHECK(predictions.size(1) == targets.size(1), "feature sizes must match");

    auto batch_size = predictions.size(0);
    auto feature_size = predictions.size(1);

    auto out = torch::zeros({1}, torch::dtype(torch::kFloat).device(predictions.device()));

    int threads = 256;
    int blocks = batch_size;
    size_t shared_mem_size = 3 * threads * sizeof(float);

    fused_cosine_similarity_loss_kernel<<<blocks, threads, shared_mem_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        feature_size
    );

    // Divide by batch_size to get mean
    auto out_host = out.clone();  // Allocate a copy to do final scaling on device or CPU
    out_host[0] /= static_cast<float>(batch_size);
    out.copy_(out_host);

    return out;
}
"""

fused_cos_sim_loss_decl = r"torch::Tensor fused_cosine_similarity_loss_cuda(torch::Tensor, torch::Tensor);"

fused_cos_sim_loss = load_inline(
    name="fused_cos_sim_loss",
    cpp_sources=fused_cos_sim_loss_decl,
    cuda_sources=fused_cos_sim_loss_src,
    functions=["fused_cosine_similarity_loss_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.fused_loss = fused_cos_sim_loss

    def forward(self, predictions, targets):
        return self.fused_loss.fused_cosine_similarity_loss_cuda(predictions, targets)
